def convert(val):
    if val is None or val.strip() == "":
        return None

    val = val.strip()

    # Liste des formats possibles
    formats = [
        "%Y",                  # 2016
        "%d/%m/%Y",            # 17/10/2018
        "%d/%m/%Y %H:%M:%S",   # 29/10/2010 15:13:13
        "%d/%m/%Y %H:%M",      # 29/10/2010 15:13
    ]

    for fmt in formats:
        try:
            dt = datetime.datetime.strptime(val, fmt)

            # Si seule l'année est fournie, on fixe au 1er janvier
            if fmt == "%Y":
                dt = datetime.datetime(dt.year, 1, 1)

            return dt
        except ValueError:
            pass

    return None" DATE NO_ENFORCE_DOMAINS
